            font-size: 16px;
            border-radius: 5px;
            cursor: pointer;
            margin-bottom: 20px;
        }

        button:hover {
            background-color: #45a049;
        }

        #joke {
            font-size: 18px;
            min-height: 60px;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>🎭 Joke Generator</h1>
        <button onclick="showJoke()">Tell Me a Joke</button>
        <p id="joke">Click the button to get a joke!</p>
    </div>

    <script>
        const jokes = [
            "Why did the programmer quit his job? Because he didn't get any arrays. 😄",
            "Why don't scientists trust atoms? Because they make up everything! ⚛️",
            "What do you call a fake noodle? An impasta! 🍝",
            "Why did the bicycle fall over? Because it was two-tired! 🚲"
        ];

        function showJoke() {
            const randomIndex = Math.floor(Math.random() * jokes.length);
            document.getElementById("joke").textContent = jokes[randomIndex];
        }
    </script>
</body>
</html>
```

**How it works:**
- **`jokes` array** — stores the 4 jokes.
- **`Math.random()`** — generates a random number between 0 and 1.
- **`Math.floor(Math.random() * jokes.length)`** — converts it into a random index (0–3) to pick a joke.
- **`textContent`** — updates the paragraph on the page with the selected joke.

